//lxrtxdy!
#pragma GCC optimize(3)
#include <bits/stdc++.h>
#define MAX_SIZE 7100
typedef long long ll;
#define INF 1000000000
using namespace std;

struct Flow {
    struct Edge {
        int u, v;
        ll f, c;
    };
    int src, sink;
    vector<Edge> e;
    vector<int> adj[MAX_SIZE];
    int d[MAX_SIZE], seen[MAX_SIZE];
    int cur[MAX_SIZE];

    void init() {
        e.clear();
        for (int i = 0; i < MAX_SIZE; i++) adj[i].clear();
    }

    void add(int u, int v, ll cap) {
        e.push_back({u, v, 0, cap});
        e.push_back({v, u, 0, 0});
        adj[u].push_back((int)e.size() - 2);
        adj[v].push_back((int)e.size() - 1);
    }

    bool bfs() {
        memset(seen, 0, sizeof(seen));
        memset(d, 0, sizeof(d));
        queue<int> q;
        q.push(src);
        seen[src] = 1;
        d[src] = 0;
        while (!q.empty()) {
            int x = q.front(); q.pop();
            for (int id : adj[x]) {
                Edge &ed = e[id];
                if (!seen[ed.v] && ed.c > ed.f) {
                    d[ed.v] = d[x] + 1;
                    q.push(ed.v);
                    seen[ed.v] = 1;
                }
            }
        }
        return seen[sink];
    }

    ll dfs(int x, ll flow) {
        if (x == sink || flow == 0) return flow;
        ll pushed = 0, add;
        for (int &i = cur[x]; i < (int)adj[x].size(); i++) {
            Edge &ed = e[adj[x][i]];
            if (d[x] + 1 == d[ed.v]) {
                ll minf = min(flow, ed.c - ed.f);
                add = dfs(ed.v, minf);
                if (add > 0) {
                    ed.f += add;
                    e[adj[x][i] ^ 1].f -= add;
                    pushed += add;
                    flow -= add;
                    if (flow == 0) break;
                }
            }
        }
        return pushed;
    }

    ll dinic() {
        ll flow = 0;
        while (bfs()) {
            memset(cur, 0, sizeof(cur));
            flow += dfs(src, INF);
        }
        return flow;
    }
};

Flow mf;
char g1[14][14];
char g2[14][14];
bool vis[14][14];
int dist[14][14];
int n;
int tgt[103];

void BFS(int sx, int sy) {
    queue<pair<pair<int, int>, int>> q;
    for (int i = 0; i < 14; i++)
        for (int j = 0; j < 14; j++)
            dist[i][j] = 111;
    dist[sx][sy] = 0;
    q.push({{sx, sy}, 0});
    int dx[4] = {1, 0, 0, -1}, dy[4] = {0, 1, -1, 0};
    while (!q.empty()) {
        auto p = q.front(); q.pop();
        int cx = p.first.first, cy = p.first.second;
        if (vis[cx][cy]) continue;
        vis[cx][cy] = true;
        dist[cx][cy] = p.second;
        for (int i = 0; i < 4; i++) {
            int nx = cx + dx[i], ny = cy + dy[i];
            if (nx < 1 || nx > n || ny < 1 || ny > n || vis[nx][ny] || g1[nx][ny] == 'Y') continue;
            q.push({{nx, ny}, p.second + 1});
        }
    }
}

int idx(int l, int x, int y) {
    return l * n * n + (x - 1) * n + y;
}

int main() {
    int i, j, k, t;
    scanf("%d%d", &n, &t);
    for (i = 1; i <= n; i++) scanf("%s", g1[i] + 1);
    for (i = 1; i <= n; i++) scanf("%s", g2[i] + 1);

    mf.src = 0;
    mf.sink = MAX_SIZE - 2;
    int sx = 0, sy = 0;
    for (i = 1; i <= n; i++) {
        for (j = 1; j <= n; j++) {
            if (g1[i][j] == 'Z') {
                sx = i; sy = j;
                break;
            }
        }
        if (sx) break;
    }

    for (i = 1; i <= n * n; i++) tgt[i] = MAX_SIZE - 3 - (n * n - i);

    BFS(sx, sy);

    for (i = 1; i <= n; i++) {
        for (j = 1; j <= n; j++) {
            if (g1[i][j] >= '0' && g1[i][j] <= '9')
                mf.add(mf.src, idx(0, i, j), g1[i][j] - '0');
            if (g2[i][j] >= '0' && g2[i][j] <= '9')
                mf.add(tgt[idx(0, i, j)], mf.sink, g2[i][j] - '0');
            mf.add(idx(0, i, j), tgt[idx(0, i, j)], INF);
        }
    }

    int dx[4] = {1, 0, 0, -1}, dy[4] = {0, 1, -1, 0};
    for (i = 1; i <= t; i++) {
        for (j = 1; j <= n; j++) {
            for (k = 1; k <= n; k++) {
                if (g1[j][k] == 'Y' || g1[j][k] == 'Z') continue;
                for (int l = 0; l < 4; l++) {
                    int tx = dx[l] + j, ty = dy[l] + k;
                    if (tx >= 1 && tx <= n && ty >= 1 && ty <= n && g1[tx][ty] != 'Y' && g1[tx][ty] != 'Z') {
                        if (dist[j][k] >= i && dist[tx][ty] >= i && g1[j][k] != 'Y' && g1[j][k] != 'Z') {
                            mf.add(idx(i-1, tx, ty), idx(i, j, k), INF);
                        }
                    }
                }
                mf.add(idx(i, j, k), tgt[idx(0, j, k)], INF);
            }
        }
    }
    printf("%lld\n", mf.dinic());
    return 0;
}
